    // === MOTION MATH ENGINE ===
    const motionInterpolate = (input, inputRange, outputRange, options = {}) => {
      const { extrapolateLeft = 'extend', extrapolateRight = 'extend' } = options;
      let i = 1;
      for (; i < inputRange.length - 1; i++) { if (inputRange[i] >= input) break; }
      const inLow = inputRange[i - 1], inHigh = inputRange[i];
      const outLow = outputRange[i - 1], outHigh = outputRange[i];
      let t = inHigh === inLow ? 0 : (input - inLow) / (inHigh - inLow);
      if (t < 0 && extrapolateLeft === 'clamp') t = 0;
      if (t > 1 && extrapolateRight === 'clamp') t = 1;
      return outLow + t * (outHigh - outLow);
    };

    const motionSpring = ({ frame, fps = 30, config = {} }) => {
      const { stiffness = 100, damping = 10, mass = 0.5 } = config;
      const w0 = Math.sqrt(stiffness / mass);
      const zeta = damping / (2 * Math.sqrt(stiffness * mass));
      const t = frame / fps;
      if (zeta < 1) {
        const wd = w0 * Math.sqrt(1 - zeta * zeta);
        return 1 - Math.exp(-zeta * w0 * t) * (Math.cos(wd * t) + (zeta * w0 / wd) * Math.sin(wd * t));
      }
      return 1 - (1 + w0 * t) * Math.exp(-w0 * t);
    };

    const motionSeedRandom = (seed) => {
      let h = 0xdeadbeef ^ (typeof seed === 'string' ? [...seed].reduce((a,c) => (a*31+c.charCodeAt(0))|0, 0) : seed);
      return () => { h = Math.imul(h ^ (h >>> 16), 2246822507); h = Math.imul(h ^ (h >>> 13), 3266489909); return ((h ^= h >>> 16) >>> 0) / 4294967296; };
    };

    const polygonPoints = (sides, innerRatio = 0, cx = 50, cy = 50, r = 50) => {
      const sideCount = Math.max(3, Math.round(Number(sides) || 3));
      const inner = clamp(Number(innerRatio) || 0, 0, 0.95);
      const star = inner > 0.001;
      const total = star ? sideCount * 2 : sideCount;
      const step = (Math.PI * 2) / total;
      const pts = [];
      for (let i = 0; i < total; i += 1) {
        const rr = star && (i % 2 === 1) ? (r * inner) : r;
        const a = -Math.PI / 2 + (i * step);
        pts.push([cx + (Math.cos(a) * rr), cy + (Math.sin(a) * rr)]);
      }
      return pts;
    };
