          if (interp === 'easeOut') return 1 - ((1 - rawT) * (1 - rawT));
          if (interp === 'easeInOut') return rawT < 0.5 ? 2 * rawT * rawT : 1 - Math.pow(-2 * rawT + 2, 2) / 2;
