                        <div key={system.id} className="border-2 border-black rounded-md p-2 bg-[#f8f8fb] text-[10px] font-black">
                          <div className="flex items-center justify-between gap-2 uppercase">
                            <span>{system.label}</span>
                            <span style={{ background: system.status === 'implemented' ? COLORS.green : system.status === 'stubbed' ? COLORS.yellow : COLORS.white, border: '2px solid #111', borderRadius: '999px', padding: '2px 8px' }}>{system.status}</span>
                          </div>
                          <div className="opacity-70 mt-1">{system.note}</div>
                        </div>
